:root {
  color-scheme: light;
  --color-bg: #f5f7fb;
  --color-surface: #ffffff;
  --color-surface-muted: #eef3ff;
  --color-surface-strong: #0f172a;
  --color-text: #0f172a;
  --color-text-soft: #475569;
  --color-text-muted: #64748b;
  --color-border: rgba(15, 23, 42, 0.1);
  --color-border-strong: rgba(59, 130, 246, 0.35);
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-soft: rgba(37, 99, 235, 0.12);
  --color-accent: #7c3aed;
  --color-success: #0f9f6e;
  --color-highlight-bg: linear-gradient(180deg, rgba(37, 99, 235, 0.08), rgba(124, 58, 237, 0.1));
  --color-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
  --color-shadow-lg: 0 24px 60px rgba(15, 23, 42, 0.14);
  --color-focus: rgba(37, 99, 235, 0.3);

  --font-family-base: "Inter", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-md: 1.125rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: clamp(1.75rem, 4vw, 2.5rem);
  --font-size-2xl: clamp(2.25rem, 6vw, 4rem);
  --line-height-tight: 1.15;
  --line-height-base: 1.6;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  --radius-sm: 0.625rem;
  --radius-md: 1rem;
  --radius-lg: 1.5rem;
  --radius-xl: 2rem;
  --radius-pill: 999px;

  --container-max: 72rem;
  --container-padding: 1rem;
  --nav-height: 4.5rem;

  --transition-fast: 180ms ease;
  --transition-base: 260ms ease;
}

* ,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-height) + var(--space-4));
}

body {
  margin: 0;
  min-width: 0;
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--color-text);
  background:
    radial-gradient(circle at top left, rgba(37, 99, 235, 0.08), transparent 32%),
    linear-gradient(180deg, #fbfcff 0%, var(--color-bg) 100%);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
a,
summary {
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
}

main,
.site-header,
.site-footer {
  width: 100%;
}

main {
  display: block;
  padding-top: calc(var(--nav-height) + var(--space-6));
}

section,
.site-footer {
  padding-inline: var(--container-padding);
}

section {
  scroll-margin-top: calc(var(--nav-height) + var(--space-5));
  padding-block: var(--space-16);
}

.site-nav,
.hero,
.features,
.pricing,
.faq,
.final-cta,
.site-footer {
  max-width: calc(var(--container-max) + (var(--container-padding) * 2));
  margin-inline: auto;
}

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.65);
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.04);
}

.site-nav {
  min-height: var(--nav-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding-inline: var(--container-padding);
  padding-block: var(--space-3);
  position: relative;
}

.nav-brand a {
  font-weight: 800;
  letter-spacing: -0.02em;
}

.nav-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.7rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.9);
  color: var(--color-text);
  cursor: pointer;
  transition: background-color var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
}

.nav-menu {
  position: absolute;
  top: calc(100% - 0.2rem);
  left: var(--container-padding);
  right: var(--container-padding);
  display: grid;
  gap: var(--space-5);
  padding: var(--space-5);
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--color-shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-0.5rem);
  pointer-events: none;
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
}

.nav-menu.is-open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  pointer-events: auto;
}

.nav-links {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-links a,
.footer-links a {
  color: var(--color-text-soft);
  transition: color var(--transition-fast);
}

.nav-links a {
  display: block;
  padding: 0.85rem 1rem;
  border-radius: var(--radius-md);
}

.nav-actions {
  display: flex;
  width: 100%;
}

.nav-actions .button {
  width: 100%;
  justify-content: center;
}

.skip-link {
  position: absolute;
  left: var(--space-4);
  top: -3rem;
  z-index: 1100;
  padding: 0.85rem 1rem;
  border-radius: var(--radius-pill);
  background: var(--color-surface-strong);
  color: #ffffff;
  transition: top var(--transition-fast);
}

.skip-link:focus-visible {
  top: var(--space-4);
}

.hero {
  display: grid;
  gap: var(--space-10);
  align-items: center;
}

.hero-content,
.final-cta-content,
.section-heading {
  max-width: 40rem;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  margin: 0 0 var(--space-4);
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius-pill);
  background: var(--color-primary-soft);
  color: var(--color-primary);
  font-size: var(--font-size-sm);
  font-weight: 700;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--color-text);
  line-height: var(--line-height-tight);
  letter-spacing: -0.03em;
}

h1 {
  margin-bottom: var(--space-5);
  font-size: var(--font-size-2xl);
}

h2 {
  margin-bottom: var(--space-4);
  font-size: var(--font-size-xl);
}

p {
  color: var(--color-text-soft);
}

.hero-description,
.section-heading p:last-child,
.final-cta-content > p:not(.eyebrow) {
  font-size: var(--font-size-md);
}

.hero-actions,
.final-cta-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-top: var(--space-8);
}

.hero-visual img {
  width: 100%;
  border-radius: var(--radius-xl);
  box-shadow: var(--color-shadow-lg);
  border: 1px solid rgba(255, 255, 255, 0.7);
}

.button,
.toggle-option {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: 0.85rem 1.2rem;
  border-radius: var(--radius-pill);
  border: 1px solid transparent;
  font-weight: 700;
  cursor: pointer;
  transition: transform var(--transition-fast), background-color var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.button:hover,
.toggle-option:hover,
.nav-toggle:hover,
.nav-links a:hover,
.footer-links a:hover {
  transform: translateY(-1px);
}

.button-primary {
  background: linear-gradient(135deg, var(--color-primary), var(--color-accent));
  color: #ffffff;
  box-shadow: 0 14px 30px rgba(37, 99, 235, 0.22);
}

.button-primary:hover {
  box-shadow: 0 18px 36px rgba(37, 99, 235, 0.28);
}

.button-secondary {
  background: rgba(255, 255, 255, 0.85);
  border-color: var(--color-border);
  color: var(--color-text);
}

.button-secondary:hover,
.nav-toggle:hover,
.nav-links a:hover {
  background: var(--color-surface-muted);
  border-color: rgba(37, 99, 235, 0.18);
}

.features-mount,
.pricing-mount,
.faq-mount {
  display: grid;
  gap: var(--space-5);
}

.features-mount {
  grid-template-columns: 1fr;
  margin-top: var(--space-8);
}

.features-mount > *,
.pricing-mount > *,
.faq-mount > * {
  min-width: 0;
}

.features-mount > * {
  padding: var(--space-6);
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--color-shadow);
}

.pricing-toggle {
  display: inline-flex;
  gap: var(--space-2);
  padding: var(--space-2);
  margin-top: var(--space-8);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.9);
}

.toggle-option {
  background: transparent;
  color: var(--color-text-soft);
}

.toggle-option.is-active,
.toggle-option[aria-pressed="true"] {
  background: var(--color-surface-strong);
  color: #ffffff;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.18);
}

.pricing-mount {
  grid-template-columns: 1fr;
  margin-top: var(--space-8);
  overflow-x: clip;
}

.pricing-mount > * {
  display: flex;
  flex-direction: column;
  padding: var(--space-6);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--color-shadow);
}

.pricing-mount > .is-featured,
.pricing-mount > [data-featured="true"],
.pricing-mount > [aria-current="true"] {
  position: relative;
  background: var(--color-highlight-bg), #ffffff;
  border-color: var(--color-border-strong);
  box-shadow: 0 24px 60px rgba(37, 99, 235, 0.18);
  transform: translateY(-0.125rem);
}

.pricing-mount > .is-featured::before,
.pricing-mount > [data-featured="true"]::before,
.pricing-mount > [aria-current="true"]::before {
  content: "推荐";
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  padding: 0.35rem 0.7rem;
  border-radius: var(--radius-pill);
  background: var(--color-surface-strong);
  color: #ffffff;
  font-size: var(--font-size-xs);
  font-weight: 800;
  letter-spacing: 0.04em;
}

.faq-mount {
  margin-top: var(--space-8);
}

.faq-mount > * {
  padding: 0;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--color-shadow);
}

.faq-mount details {
  width: 100%;
}

.faq-mount summary,
.faq-mount button,
.faq-mount [role="button"] {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-5) var(--space-6);
  background: transparent;
  border: 0;
  color: var(--color-text);
  font-weight: 700;
  text-align: left;
  cursor: pointer;
}

.faq-mount summary::-webkit-details-marker {
  display: none;
}

.faq-mount summary::after,
.faq-mount button::after,
.faq-mount [role="button"]::after {
  content: "+";
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--color-surface-muted);
  color: var(--color-primary);
  font-size: 1.25rem;
  transition: transform var(--transition-base), background-color var(--transition-fast), color var(--transition-fast);
}

.faq-mount details[open] summary,
.faq-mount .is-open > summary,
.faq-mount .is-open > button,
.faq-mount [aria-expanded="true"] {
  background: rgba(37, 99, 235, 0.06);
  color: var(--color-primary-hover);
}

.faq-mount details[open] summary::after,
.faq-mount .is-open > summary::after,
.faq-mount .is-open > button::after,
.faq-mount [aria-expanded="true"]::after {
  content: "−";
  background: var(--color-primary);
  color: #ffffff;
  transform: rotate(180deg);
}

.faq-mount details > :not(summary) {
  padding: 0 var(--space-6) var(--space-6);
  color: var(--color-text-soft);
}

.final-cta-content {
  padding: clamp(1.5rem, 5vw, 3rem);
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(37, 99, 235, 0.92));
  color: #ffffff;
  box-shadow: var(--color-shadow-lg);
}

.final-cta-content h2,
.final-cta-content p {
  color: inherit;
}

.site-footer {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: 0 var(--container-padding) var(--space-10);
}

.footer-meta p {
  margin-bottom: 0;
  color: var(--color-text-muted);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}

.button:focus-visible,
.toggle-option:focus-visible,
.nav-toggle:focus-visible,
.nav-links a:focus-visible,
.footer-links a:focus-visible,
.faq-mount summary:focus-visible,
.faq-mount button:focus-visible,
.faq-mount [role="button"]:focus-visible {
  box-shadow: 0 0 0 4px var(--color-focus);
  outline: none;
}

@media (min-width: 40rem) {
  :root {
    --container-padding: 1.5rem;
  }

  .hero-actions,
  .final-cta-actions {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .hero-actions .button,
  .final-cta-actions .button {
    width: auto;
  }

  .features-mount {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pricing-mount {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .site-footer {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

@media (min-width: 64rem) {
  :root {
    --container-padding: 2rem;
  }

  .nav-toggle {
    display: none;
  }

  .nav-menu {
    position: static;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex: 1;
    padding: 0;
    margin-left: var(--space-8);
    background: transparent;
    border: 0;
    box-shadow: none;
    opacity: 1;
    visibility: visible;
    transform: none;
    pointer-events: auto;
  }

  .nav-links {
    display: flex;
    align-items: center;
    gap: var(--space-2);
  }

  .nav-actions {
    width: auto;
  }

  .nav-actions .button {
    width: auto;
  }

  .hero {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  }

  .features-mount {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pricing-mount {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .button:hover,
  .toggle-option:hover,
  .nav-toggle:hover,
  .nav-links a:hover,
  .footer-links a:hover,
  .pricing-mount > .is-featured,
  .pricing-mount > [data-featured="true"],
  .pricing-mount > [aria-current="true"] {
    transform: none;
  }
}

