  /**
   * Escapes a string for safe HTML interpolation.
   *
   * @param {unknown} value Source value.
   * @returns {string} Escaped HTML string.
   */
  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /**
   * Safely sets text content on an element.
   *
   * @param {Element|null|undefined} element Target element.
   * @param {string} value Text value.
   * @returns {void}
   */
  function setText(element, value) {
    if (element) {
      element.textContent = value;
    }
  }

  /**
   * Safely sets HTML content on an element.
   *
   * @param {Element|null|undefined} element Target element.
   * @param {string} value HTML string.
   * @returns {void}
   */
  function setHtml(element, value) {
    if (element) {
      element.innerHTML = value;
    }
  }

  /**
   * Safely sets an attribute on an element.
   *
   * @param {Element|null|undefined} element Target element.
   * @param {string} name Attribute name.
   * @param {string} value Attribute value.
   * @returns {void}
   */
  function setAttribute(element, name, value) {
    if (element) {
      element.setAttribute(name, value);
    }
  }

  /**
   * Creates button-style anchor markup from action configuration.
   *
   * @param {string} buttonClass CSS class name to append.
   * @param {{label?: string, href?: string, ariaLabel?: string}|null|undefined} action Action config.
   * @returns {string} Anchor markup or empty string if config is invalid.
   */
  function createButtonLinkMarkup(buttonClass, action) {
    if (!action || !action.label || !action.href) {
      return '';
    }

    const aria = action.ariaLabel ? ' aria-label="' + escapeHtml(action.ariaLabel) + '"' : '';
    return '<a class="button ' + escapeHtml(buttonClass) + '" href="' + escapeHtml(action.href) + '"' + aria + '>' + escapeHtml(action.label) + '</a>';
  }

  /**
   * Ensures that at most one pricing plan remains recommended.
   * The first truthy recommended plan wins; all others are downgraded.
   *
   * @param {Array<object>} plans Source plans.
   * @returns {Array<object>} Normalized plans.
   */
  function normalizeRecommendedPlans(plans) {
    let recommendedUsed = false;
    const safePlans = Array.isArray(plans) ? plans : [];

    return safePlans.map(function mapPlan(plan) {
      const nextPlan = Object.assign({}, plan);

      if (nextPlan.recommended && !recommendedUsed) {
        recommendedUsed = true;
        nextPlan.recommended = true;
      } else {
        nextPlan.recommended = false;
      }

      return nextPlan;
    });
  }

  /**
   * Returns normalized pricing plan data.
   *
   * @returns {Array<object>} Safe plans list.
   */
  function getSafePlans() {
    return normalizeRecommendedPlans(APP_CONFIG.pricing && APP_CONFIG.pricing.plans ? APP_CONFIG.pricing.plans : []);
  }

  /**
   * Formats a numeric price in CNY.
   *
   * @param {number} value Price value.
   * @returns {string} Formatted currency string or fallback text.
   */
  function formatPrice(value) {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      return APP_CONFIG.pricing.fallbackText;
    }

    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: 'CNY',
      maximumFractionDigits: 0
    }).format(value);
  }

  /**
   * Resolves displayed pricing copy for a plan and period.
   *
   * @param {{prices?: {monthly?: number|null, yearly?: number|null}}} plan Plan config.
   * @param {'monthly'|'yearly'} billingPeriod Active period.
   * @returns {{value: string, period: string, isFallback: boolean}} Display info.
   */
  function getPricingDisplay(plan, billingPeriod) {
    const prices = plan && typeof plan === 'object' && plan.prices ? plan.prices : {};
    const rawPrice = prices[billingPeriod];

    if (typeof rawPrice !== 'number' || Number.isNaN(rawPrice)) {
      return {
        value: APP_CONFIG.pricing.fallbackText,
        period: APP_CONFIG.pricing.fallbackPeriodText,
        isFallback: true
      };
    }

    return {
      value: formatPrice(rawPrice),
      period: APP_CONFIG.pricing.periods[billingPeriod] || '',
      isFallback: false
    };
  }

