  /**
   * Creates pricing plan card markup.
   *
   * @param {object} plan Pricing plan.
   * @param {'monthly'|'yearly'} billingPeriod Active billing period.
   * @returns {string} Pricing card markup.
   */
  function createPricingCardMarkup(plan, billingPeriod) {
    const display = getPricingDisplay(plan, billingPeriod);
    const planFeatures = Array.isArray(plan.features) ? plan.features : [];
    const recommendedMarkup = plan.recommended
      ? '<p class="pricing-badge" aria-label="推荐方案">' + escapeHtml(APP_CONFIG.pricing.recommendedBadge) + '</p>'
      : '';
    const fallbackClass = display.isFallback ? ' is-fallback' : '';

    return [
      '<article class="pricing-card' + (plan.recommended ? ' is-recommended' : '') + '"' + (plan.recommended ? ' data-recommended="true"' : '') + '>',
      recommendedMarkup,
      '<h3>' + escapeHtml(plan.name || '') + '</h3>',
      '<p>' + escapeHtml(plan.description || '') + '</p>',
      '<div class="pricing-value' + fallbackClass + '">',
      '  <span class="pricing-amount" data-role="price-value">' + escapeHtml(display.value) + '</span>',
      '  <span class="pricing-period" data-role="price-period">' + escapeHtml(display.period) + '</span>',
      '</div>',
      '<ul class="pricing-features">',
      planFeatures.map(function renderFeature(feature) {
        return '<li>' + escapeHtml(feature) + '</li>';
      }).join(''),
      '</ul>',
      createButtonLinkMarkup('button-secondary', plan.cta),
      '</article>'
    ].join('');
  }

