  /**
   * Syncs pricing toggle button visual and aria states.
   *
   * @returns {void}
   */
  function syncPricingToggleState() {
    if (!dom.pricingToggleButtons || dom.pricingToggleButtons.length < 2) {
      return;
    }

    const isMonthly = state.billingPeriod === 'monthly';
    const monthlyButton = dom.pricingToggleButtons[0];
    const yearlyButton = dom.pricingToggleButtons[1];

    monthlyButton.classList.toggle('is-active', isMonthly);
    yearlyButton.classList.toggle('is-active', !isMonthly);
    monthlyButton.setAttribute('aria-pressed', isMonthly ? 'true' : 'false');
    yearlyButton.setAttribute('aria-pressed', isMonthly ? 'false' : 'true');
  }

