  /**
   * Updates navigation menu open state and ARIA attributes.
   *
   * @param {boolean} isOpen Whether the mobile menu is open.
   * @returns {void}
   */
  function setMenuOpen(isOpen) {
    state.isMenuOpen = Boolean(isOpen);

    if (dom.navMenu) {
      dom.navMenu.classList.toggle('is-open', state.isMenuOpen);
    }

    if (dom.navToggle) {
      dom.navToggle.setAttribute('aria-expanded', state.isMenuOpen ? 'true' : 'false');
      dom.navToggle.setAttribute(
        'aria-label',
        state.isMenuOpen ? APP_CONFIG.navigation.toggleCloseLabel : APP_CONFIG.navigation.toggleOpenLabel
      );
    }
  }

  /**
   * Toggles a FAQ item open or closed while preserving support for multiple open items.
   *
   * @param {HTMLButtonElement} button Trigger button.
   * @returns {void}
   */
  function toggleFaqItem(button) {
    const controlsId = button.getAttribute('aria-controls');

    if (!controlsId) {
      return;
    }

    const panel = document.getElementById(controlsId);

    if (!panel) {
      return;
    }

    const isExpanded = button.getAttribute('aria-expanded') === 'true';
    button.setAttribute('aria-expanded', isExpanded ? 'false' : 'true');
    panel.hidden = isExpanded;
  }

  /**
   * Smoothly scrolls to an in-page anchor and focuses a visible heading or target container.
   *
   * @param {string} hash Anchor hash.
   * @returns {void}
   */
  function scrollToAnchor(hash) {
    if (!hash || hash.charAt(0) !== '#') {
      return;
    }

    const target = document.querySelector(hash);

    if (!target) {
      return;
    }

    target.scrollIntoView({ behavior: 'smooth', block: 'start' });

    window.setTimeout(function focusHeading() {
      const heading = target.querySelector('h1, h2, h3, [data-scroll-focus]');
      const focusTarget = heading || target;
      const previousTabIndex = focusTarget.getAttribute('tabindex');

      if (!focusTarget.hasAttribute('tabindex')) {
        focusTarget.setAttribute('tabindex', '-1');
      }

      if (typeof focusTarget.focus === 'function') {
        focusTarget.focus({ preventScroll: true });
      }

      if (previousTabIndex === null) {
        focusTarget.addEventListener('blur', function handleBlur() {
          focusTarget.removeAttribute('tabindex');
        }, { once: true });
      }
    }, 320);
  }

  /**
   * Handles global click behavior for smooth anchor scrolling and menu auto-close.
   *
   * @param {MouseEvent} event Click event.
   * @returns {void}
   */
  function handleDocumentClick(event) {
    const target = event.target;

    if (!(target instanceof Element)) {
      return;
    }

    const anchor = target.closest('a[href^="#"]');

    if (!anchor) {
      return;
    }

    const href = anchor.getAttribute('href');

    if (!href || href === '#') {
      if (dom.navMenu && dom.navMenu.contains(anchor)) {
        setMenuOpen(false);
      }
      return;
    }

    const targetElement = document.querySelector(href);

    if (!targetElement) {
      if (dom.navMenu && dom.navMenu.contains(anchor)) {
        setMenuOpen(false);
      }
      return;
    }

    event.preventDefault();
    scrollToAnchor(href);

    if (window.history && typeof window.history.pushState === 'function') {
      window.history.pushState(null, '', href);
    }

    if (dom.navMenu && dom.navMenu.contains(anchor)) {
      setMenuOpen(false);
    }
  }

  /**
   * Binds application interactions.
   *
   * @returns {void}
   */
  function bindEvents() {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', function onToggleClick() {
        setMenuOpen(!state.isMenuOpen);
      });
    }

    if (dom.pricingToggleButtons && dom.pricingToggleButtons.length >= 2) {
      dom.pricingToggleButtons[0].addEventListener('click', function onMonthlyClick() {
        if (state.billingPeriod !== 'monthly') {
          state.billingPeriod = 'monthly';
          renderPricingCards();
          syncPricingToggleState();
        }
      });

      dom.pricingToggleButtons[1].addEventListener('click', function onYearlyClick() {
        if (state.billingPeriod !== 'yearly') {
          state.billingPeriod = 'yearly';
          renderPricingCards();
          syncPricingToggleState();
        }
      });
    }

    if (dom.faqMount) {
      dom.faqMount.addEventListener('click', function onFaqClick(event) {
        const target = event.target;

        if (!(target instanceof Element)) {
          return;
        }

        const button = target.closest('.faq-toggle');

        if (!(button instanceof HTMLButtonElement)) {
          return;
        }

        toggleFaqItem(button);
      });
    }

    document.addEventListener('click', handleDocumentClick);

    document.addEventListener('keydown', function onDocumentKeydown(event) {
      if (event.key === 'Escape' && state.isMenuOpen) {
        setMenuOpen(false);
        if (dom.navToggle && typeof dom.navToggle.focus === 'function') {
          dom.navToggle.focus();
        }
      }
    });
  }

  /**
   * Renders all page sections from the centralized config.
   *
   * @returns {void}
   */
  function renderApp() {
    renderNavigation();
    renderHero();
    renderFeatures();
    renderPricing();
    renderFaq();
    renderFinalCta();
    renderFooter();
  }

  /**
   * Initializes the application after DOM is ready.
   *
   * @returns {void}
   */
  function init() {
    cacheDom();
    renderApp();
    setMenuOpen(false);
    bindEvents();
  }

  document.addEventListener('DOMContentLoaded', init);
})();
